{
  "severity": "critical",
  "host_observations": [
    {"host": "WS-DEV-37.corp.local", "role": "endpoint", "user": "p.dvorak", "target_api": "api.corp.local/v1/admin/users", "first_seen": "2033-04-22T17:48:08+0000", "last_seen": "2033-04-22T17:52:30+0000"}
  ],
  "attack_progression": [
    {"step": 1, "tactic": "Capture existing JWT + decode header/payload", "technique": "T1606", "what_happened": "At 2033-04-22 17:48:08 UTC on WS-DEV-37, AMSI EID 4104 captured a powershell.exe scriptblock with Base64Url decode helper functions (ToB64Url / FromB64Url) AND a sample JWT containing header {alg:HS256,typ:JWT,kid:key-2024-01} and payload {sub:alice@corp.local,role:user,exp:...}. The script logs the decoded header + payload — typical JWT-tooling reconnaissance.", "chain_reason": "Decoding a captured JWT is the precondition step of T1606 JWT forge — the attacker reads the existing claims structure (sub, role, exp, kid) before crafting a privilege-escalated forgery."},
    {"step": 2, "tactic": "Forge alg=none JWT with role=admin payload", "technique": "T1606", "what_happened": "At 2033-04-22 17:48:24, AMSI EID 4104 captured a powershell.exe scriptblock constructing a new JWT with header '{\"alg\":\"none\",\"typ\":\"JWT\"}' AND payload '{\"sub\":\"alice@corp.local\",\"role\":\"admin\",\"exp\":...}' AND EMPTY signature ('$forgedNone = \"$noneHdr.$adminPayload.\"'). The role claim is escalated from 'user' to 'admin'. Rule 4104 triggered.", "chain_reason": "The alg=none JWT attack exploits servers that incorrectly trust the header's 'alg' value: if the server sees 'alg':'none' AND does not enforce that signed-by-key MUST be required, it accepts the token without signature verification. The role='admin' claim then grants admin access."},
    {"step": 3, "tactic": "Forge HS256 JWT with attacker-controlled key (RS256→HS256 confusion)", "technique": "T1606", "what_happened": "At 2033-04-22 17:48:34, AMSI EID 4104 captured a powershell.exe scriptblock using New-Object System.Security.Cryptography.HMACSHA256 with key bytes 'attacker-knows-this-secret' to compute an HMAC signature over the same admin-role payload + header {alg:HS256,kid:key-2024-01}. The forged JWT uses kid='key-2024-01' (matching the legitimate token's kid). Rule 4104 secondary.", "chain_reason": "The RS256→HS256 key confusion attack exploits servers that look up the kid in their key store, retrieve the RSA public key bytes, and then use them as the HS256 HMAC secret. The attacker, knowing the public key (which is published), can forge an HS256 signature the server will accept. With role='admin' the attacker becomes admin."},
    {"step": 4, "tactic": "WAF + app-layer alerts on replay to /v1/admin/users + tool literals", "technique": "T1606", "what_happened": "At 2033-04-22 17:48:48, Sysmon EID 3 captured two outbound HTTPS requests from powershell.exe to https://api.corp.local/v1/admin/users with Authorization: Bearer <forged-jwt>. Corp WAF logged: rule 31540 'Authorization Bearer with alg=none claim' on the first request, AND app-layer log on api.corp.local recorded: 'JWT claims role=admin from sub=alice@corp.local who has corp role=user' (mismatch). UA 'PostmanRuntime/7.31' (impersonating Postman). AMSI EID 4104 also captured tool literals: 'jwt_tool.py <token> -X a (alg=none confusion)', 'jwt_tool.py <token> -X s -pk pubkey.pem (RS256->HS256 key confusion)', 'jwt_tool.py <token> -X i -ih kid -hv \"..\\..\\..\\dev\\null\" (kid path-traversal injection)', 'hashcat -m 16500 jwt.txt rockyou.txt (HS256 secret brute-force)'. Rules 31540 + 91650 triggered.", "chain_reason": "WAF rule 31540 fires on alg=none in Bearer JWT (extremely rare in legitimate corp tokens — the corp JWT bundle uses HS256/RS256). App-layer mismatch (claimed role=admin while alice's actual corp role is user) fires rule 91650. AMSI tool literals confirm operator-style attack notes."}
  ],
  "time_window": {"start": "2033-04-22T17:48:08+0000", "end": "2033-04-22T17:52:30+0000"},
  "alert_count": 3,
  "unique_steps": 4
}
